const fs = require('fs');
    // ...
const jsdom = require('jsdom');
    // ...
const logger = function(options = {}) {
  const options_def = {
    data: {},
    dest: '.',
    name: '',
    import: 'external',
    type: 'graph',
    svg: { width: 900, height: 600 },
    margin: {top: 50, right: 50, bottom: 50, left: 50}
  };
  options = Object.assign({}, options_def, options);

  // main struct
  const dom = new jsdom.JSDOM('<!DOCTYPE html>');
  options.doc = dom.window.document;

  const format = new formats[options.type](options);
  format.import_style();
  format.import_scripts();

  fs.writeFile(
    `${options.dest}/${options.name}_${options.type}.html`,
    dom.serialize(), {},
    () => { console.log(`>> you can open ${options.type}_data.html in a web browser`); }
  );
}
